1	/**
2	 * Stripe client singleton — lazy-initialised on first use so that
3	 * Next.js can evaluate this module at build time without requiring
4	 * STRIPE_SECRET_KEY in the build environment.
5	 */
6	import Stripe from 'stripe';
7	
8	let _stripe: Stripe | undefined;
9	
10	function getStripeClient(): Stripe {
11	  if (_stripe) return _stripe;
12	  const key = process.env.STRIPE_SECRET_KEY;
13	  if (!key) {
14	    throw new Error('STRIPE_SECRET_KEY must be set in environment variables');
15	  }
16	  _stripe = new Stripe(key, { apiVersion: '2026-02-25.clover' });
17	  return _stripe;
18	}
19	
20	/**
21	 * Lazy singleton Stripe client.
22	 * The STRIPE_SECRET_KEY check is deferred until the first actual API call.
23	 */
24	export const stripeClient: Stripe = new Proxy({} as Stripe, {
25	  get(_target, prop: string | symbol) {
26	    return getStripeClient()[prop as keyof Stripe];
27	  },
28	});
