1	/**
2	 * Per-school Stripe client factory.
3	 *
4	 * Normal production school Stripe operations are Connect-only. The returned
5	 * school client is Hilo's platform Stripe client plus a required
6	 * `stripeAccount` request option for the school's connected account.
7	 */
8	import { db } from '@/lib/db';
9	import * as schema from '@/lib/schema';
10	import { stripeClient } from '@/lib/stripe';
11	import { and, eq, isNull } from 'drizzle-orm';
12	import type Stripe from 'stripe';
13	
14	interface CacheEntry {
15	  client: Stripe;
16	  stripeAccountId: string;
17	  livemode: boolean;
18	  requestOptions: Stripe.RequestOptions;
19	  expiresAt: number;
20	}
21	
22	const CACHE_TTL_MS = 5 * 60 * 1000;
23	const cache = new Map<string, CacheEntry>();
24	const STRIPE_CONNECT_ACCOUNT_ID_PATTERN = /^acct_[A-Za-z0-9]+$/;
25	
26	/**
27	 * Result of resolving a school's Stripe client.
28	 *
29	 * `type: 'school'` → platform client scoped by Connect `stripeAccount`
30	 * `type: 'platform'` → platform singleton for non-school-owned operations
31	 */
32	export type ResolvedStripeClient =
33	  | {
34	      type: 'school';
35	      client: Stripe;
36	      schoolId: string;
37	      stripeAccountId: string;
38	      livemode: boolean;
39	      requestOptions: Stripe.RequestOptions;
40	    }
41	  | {
42	      type: 'configuration_error';
43	      schoolId: string;
44	      stripeAccountId: string | null;
45	      code: 'STRIPE_CONNECT_REQUIRED' | 'STRIPE_LEGACY_MODE_BLOCKED';
46	      message: string;
47	    }
48	  | {
49	      type: 'platform';
50	      client: Stripe;
51	    };
52	
53	function isStripeConnectMode(mode: string | null | undefined): boolean {
54	  return (
55	    mode === 'connect' || mode === 'connect_account' || mode === 'account_link'
56	  );
57	}
58	
59	export function normalizeStripeConnectAccountId(value: unknown): string | null {
60	  if (typeof value !== 'string') return null;
61	  const trimmed = value.trim();
62	  return STRIPE_CONNECT_ACCOUNT_ID_PATTERN.test(trimmed) ? trimmed : null;
63	}
64	
65	export function isValidStripeConnectAccountId(value: unknown): value is string {
66	  return normalizeStripeConnectAccountId(value) !== null;
67	}
68	
69	function connectRequiredError(
70	  schoolId: string,
71	  stripeAccountId: string | null,
72	): ResolvedStripeClient {
73	  return {
74	    type: 'configuration_error',
75	    schoolId,
76	    stripeAccountId,
77	    code: 'STRIPE_CONNECT_REQUIRED',
78	    message:
79	      'School Stripe operations require a Stripe Connect account. Reconnect Stripe from Admin Settings > Integrations.',
80	  };
81	}
82	
83	function legacyModeBlockedError(
84	  schoolId: string,
85	  stripeAccountId: string | null,
86	): ResolvedStripeClient {
87	  return {
88	    type: 'configuration_error',
89	    schoolId,
90	    stripeAccountId,
91	    code: 'STRIPE_LEGACY_MODE_BLOCKED',
92	    message:
93	      'Legacy Stripe OAuth and restricted-key credentials are blocked for production school operations. Reconnect Stripe with Account Links from Admin Settings > Integrations.',
94	  };
95	}
96	
97	/**
98	 * Fetch the appropriate Stripe client for a school.
99	 *
100	 * - Returns `{ type: 'school' }` only for Connect mode with `stripeAccountId`.
101	 * - Returns `{ type: 'configuration_error' }` for legacy OAuth/restricted-key
102	 *   rows so normal production school operations fail closed before Stripe I/O.
103	 * - Returns `{ type: 'platform' }` when no school Stripe row exists.
104	 */
105	export async function getStripeClientForSchool(
106	  schoolId: string,
107	): Promise<ResolvedStripeClient> {
108	  const cached = cache.get(schoolId);
109	  if (cached && cached.expiresAt > Date.now()) {
110	    return {
111	      type: 'school',
112	      client: cached.client,
113	      schoolId,
114	      stripeAccountId: cached.stripeAccountId,
115	      livemode: cached.livemode,
116	      requestOptions: cached.requestOptions,
117	    };
118	  }
119	  cache.delete(schoolId);
120	
121	  const row = await db.query.schoolStripeIntegrations.findFirst({
122	    where: and(
123	      eq(schema.schoolStripeIntegrations.flightSchoolId, schoolId),
124	      isNull(schema.schoolStripeIntegrations.deauthorizedAt),
125	    ),
126	    columns: {
127	      mode: true,
128	      stripeAccountId: true,
129	      livemode: true,
130	      restrictedKeyEncrypted: true,
131	    },
132	  });
133	
134	  if (!row) {
135	    return { type: 'platform', client: stripeClient };
136	  }
137	
138	  if (isStripeConnectMode(row.mode)) {
139	    const stripeAccountId = normalizeStripeConnectAccountId(
140	      row.stripeAccountId,
141	    );
142	    if (!stripeAccountId) {
143	      return connectRequiredError(schoolId, null);
144	    }
145	    const requestOptions = { stripeAccount: stripeAccountId };
146	    cache.set(schoolId, {
147	      client: stripeClient,
148	      stripeAccountId,
149	      livemode: row.livemode,
150	      requestOptions,
151	      expiresAt: Date.now() + CACHE_TTL_MS,
152	    });
153	    return {
154	      type: 'school',
155	      client: stripeClient,
156	      schoolId,
157	      stripeAccountId,
158	      livemode: row.livemode,
159	      requestOptions,
160	    };
161	  }
162	
163	  if (
164	    row.mode === 'oauth' ||
165	    row.mode === 'restricted_key' ||
166	    row.restrictedKeyEncrypted
167	  ) {
168	    return legacyModeBlockedError(schoolId, row.stripeAccountId ?? null);
169	  }
170	
171	  return connectRequiredError(schoolId, row.stripeAccountId ?? null);
172	}
173	
174	/** Invalidate the cached per-school client — call after key rotation. */
175	export function clearSchoolStripeClient(schoolId: string): void {
176	  cache.delete(schoolId);
177	}
178	
179	/** Exposed for tests — clears the full cache. */
180	export function __clearStripeClientCacheForTests(): void {
181	  cache.clear();
182	}
