1	/**
2	 * AES-256-GCM wrap/unwrap for per-school Stripe restricted keys stored in
3	 * `flight_schools.stripe_legacy_restricted_key`.
4	 *
5	 * Requires `HILO_STRIPE_KEY_ENCRYPTION_KEY` in the environment — a long
6	 * passphrase (≥ 32 chars recommended). The key is SHA-256'd to derive the
7	 * 32-byte AES key, so the env var itself can be any length. Never log or
8	 * export the derived key.
9	 *
10	 * Storage format: `iv:tag:ciphertext` — all base64. 3-field invariant; any
11	 * other shape is rejected.
12	 *
13	 * Mirrors the pattern in src/lib/quickbooks.ts (QuickBooks token encryption)
14	 * so operational semantics match: key rotation = re-encrypt via Neon SQL
15	 * with the new passphrase after deploying a new env var.
16	 */
17	import crypto from 'node:crypto';
18	
19	function getEncryptionKey(): Buffer {
20	  const key = process.env.HILO_STRIPE_KEY_ENCRYPTION_KEY;
21	  if (!key) {
22	    throw new Error(
23	      'Missing HILO_STRIPE_KEY_ENCRYPTION_KEY — required to read/write per-school Stripe restricted keys',
24	    );
25	  }
26	  return crypto.createHash('sha256').update(key).digest();
27	}
28	
29	/** Encrypt a Stripe restricted key for at-rest storage. */
30	export function encryptStripeKey(plaintext: string): string {
31	  if (!plaintext) throw new Error('Refusing to encrypt empty plaintext');
32	  const key = getEncryptionKey();
33	  const iv = crypto.randomBytes(12);
34	  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
35	  const encrypted = Buffer.concat([
36	    cipher.update(plaintext, 'utf8'),
37	    cipher.final(),
38	  ]);
39	  const tag = cipher.getAuthTag();
40	  return `${iv.toString('base64')}:${tag.toString('base64')}:${encrypted.toString('base64')}`;
41	}
42	
43	/**
44	 * Decrypt a Stripe restricted key. Throws on any corruption — callers must
45	 * treat failure as "key unusable; fall back to platform-only behavior" AND
46	 * alert the operator that a stored key is broken.
47	 */
48	export function decryptStripeKey(encoded: string): string {
49	  const parts = encoded.split(':');
50	  if (parts.length !== 3) {
51	    throw new Error(
52	      'Malformed encrypted Stripe key — expected iv:tag:ciphertext (3 base64 fields)',
53	    );
54	  }
55	  const [ivB64, tagB64, dataB64] = parts;
56	  const key = getEncryptionKey();
57	  const iv = Buffer.from(ivB64, 'base64');
58	  const tag = Buffer.from(tagB64, 'base64');
59	  const data = Buffer.from(dataB64, 'base64');
60	  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
61	  decipher.setAuthTag(tag);
62	  return decipher.update(data) + decipher.final('utf8');
63	}
