1	export interface StripeRecoveryIssueLike {
2	  code?: string | null;
3	  statusCode?: number | null;
4	  type?: string | null;
5	  message?: string | null;
6	}
7	
8	export function isStripeReauthorizationIssue(
9	  issue: StripeRecoveryIssueLike,
10	): boolean {
11	  return (
12	    issue.code === 'api_key_expired' ||
13	    issue.code === 'invalid_api_key' ||
14	    issue.code === 'application_access_not_authorized' ||
15	    issue.type === 'StripeAuthenticationError' ||
16	    issue.statusCode === 401
17	  );
