1	export type StripeAppOAuthMode = 'live' | 'sandbox';
2	
3	export interface StripeIntegrationStatusInput {
4	  mode?: string | null;
5	  stripeAccountId?: string | null;
6	  hasRestrictedKey?: boolean | null;
7	  hasWebhookSecret?: boolean | null;
8	  livemode?: boolean | null;
9	  connectionStatus?: string | null;
10	  chargesEnabled?: boolean | null;
11	  detailsSubmitted?: boolean | null;
12	  lastHealthCheckStatus?: string | null;
13	  permissionDiagnostics?: {
14	    reauthorizationRequired?: boolean | null;
15	  } | null;
16	}
17	
18	export interface StripeIntegrationCardState {
19	  connectedViaOAuth: boolean;
20	  connectedViaPrivateSandbox: boolean;
21	  needsOAuthReconnect: boolean;
22	  connected: boolean;
23	  incomplete: boolean;
24	  webhookMissing: boolean;
25	  reauthorizationRequired: boolean;
26	  failed: boolean;
27	  onboardingIncomplete: boolean;
28	  paymentsReady: boolean;
29	  statusLabel: string;
30	  statusTone: 'success' | 'warning' | 'neutral';
31	}
32	
33	export function resolveStripeAppOAuthModeForHostname(
34	  hostname: string | null | undefined,
35	): StripeAppOAuthMode {
36	  const normalized = (hostname ?? '').toLowerCase().split(':')[0];
37	  return normalized === 'app.hilo.ai' ? 'live' : 'sandbox';
38	}
39	
40	export function normalizeStripeAppOAuthMode(
41	  value: string | null | undefined,
42	): StripeAppOAuthMode | null {
43	  if (value === 'sandbox' || value === 'test') return 'sandbox';
44	  if (value === 'live') return 'live';
45	  return null;
46	}
47	
48	export function resolveStripeAppOAuthModeForRequest(args: {
49	  hostname: string | null | undefined;
50	  requestedMode?: string | null;
51	}): StripeAppOAuthMode {
52	  const hostMode = resolveStripeAppOAuthModeForHostname(args.hostname);
53	  if (hostMode === 'sandbox') return 'sandbox';
54	  return normalizeStripeAppOAuthMode(args.requestedMode) ?? 'live';
55	}
56	
57	export function validateStripeWebhookSigningSecret(value: string): {
58	  ok: boolean;
59	  value: string;
60	  error: string | null;
61	} {
62	  const trimmed = value.trim();
63	  if (!trimmed.startsWith('whsec_') || trimmed.length < 12) {
64	    return {
65	      ok: false,
66	      value: trimmed,
67	      error: 'Stripe webhook signing secret must start with whsec_.',
68	    };
69	  }
70	  return { ok: true, value: trimmed, error: null };
71	}
72	
73	export function maskStripeSecretLastFour(
74	  lastFour: string | null | undefined,
75	): string | null {
76	  return lastFour ? `****${lastFour}` : null;
77	}
78	
79	export function deriveStripeIntegrationCardState(
80	  integration: StripeIntegrationStatusInput | null | undefined,
81	): StripeIntegrationCardState {
82	  const connectedViaOAuth =
83	    integration?.mode === 'oauth' &&
84	    Boolean(integration?.stripeAccountId && integration?.hasRestrictedKey);
85	  const onboardingIncomplete =
86	    connectedViaOAuth &&
87	    (integration?.connectionStatus === 'onboarding_incomplete' ||
88	      integration?.detailsSubmitted === false);
89	  const paymentsReady =
90	    connectedViaOAuth && integration?.chargesEnabled === true;
91	  const connectedViaPrivateSandbox =
92	    integration?.mode === 'restricted_key' &&
93	    integration?.livemode === false &&
94	    Boolean(integration?.stripeAccountId && integration?.hasRestrictedKey);
95	  const needsOAuthReconnect =
96	    integration?.mode === 'restricted_key' &&
97	    !connectedViaPrivateSandbox &&
98	    Boolean(integration?.stripeAccountId || integration?.hasRestrictedKey);
99	  const connected = connectedViaOAuth || connectedViaPrivateSandbox;
100	  const incomplete =
101	    !connected &&
102	    Boolean(integration?.stripeAccountId || integration?.hasRestrictedKey);
103	  const webhookMissing = connectedViaOAuth && !integration?.hasWebhookSecret;
104	  const reauthorizationRequired =
105	    integration?.permissionDiagnostics?.reauthorizationRequired === true;
106	  const failed =
107	    integration?.lastHealthCheckStatus === 'failed' ||
108	    needsOAuthReconnect ||
109	    webhookMissing ||
110	    reauthorizationRequired;
111	  const statusLabel = failed
112	    ? reauthorizationRequired
113	      ? 'Reconnect required'
114	      : webhookMissing
115	        ? 'Webhook missing'
116	        : 'Needs attention'
117	    : onboardingIncomplete
118	      ? 'Onboarding incomplete'
119	      : connected
120	        ? 'Connected'
121	        : incomplete
122	          ? 'Incomplete'
123	          : 'Not connected';
124	  const statusTone: StripeIntegrationCardState['statusTone'] = failed
125	    ? 'warning'
126	    : onboardingIncomplete
127	      ? 'warning'
128	      : connected
129	        ? 'success'
130	        : 'neutral';
131	
132	  return {
133	    connectedViaOAuth,
134	    connectedViaPrivateSandbox,
135	    needsOAuthReconnect,
136	    connected,
137	    incomplete,
138	    webhookMissing,
139	    reauthorizationRequired,
140	    failed,
141	    onboardingIncomplete,
142	    paymentsReady,
143	    statusLabel,
144	    statusTone,
145	  };
146	}
