7	/**
8	 * Error thrown by `retrieveCustomerWithFallback` when a customer cannot be
9	 * resolved on the school's Connect account. Callers convert this into HTTP
10	 * errors rather than letting the raw Stripe error surface as a 502.
11	 */
12	export class ProvidedIdNotFoundError extends Error {
