32	export interface SchoolConnectContext {
33	  readonly schoolId: string;
34	  readonly stripeConnectAccountId: string | null;
35	  readonly chargesEnabled: boolean;
36	  readonly accountStatus: string;
37	}
38	
39	/**
40	 * Read the school's cached Stripe Connect state. Used by `retrieveCustomerWithFallback`
41	 * and by routes that gate billing on Connect activation.
42	 */
43	export async function getSchoolConnectContext(
44	  schoolId: string,
45	): Promise<SchoolConnectContext | null> {
46	  const row = await db.query.flightSchools.findFirst({
47	    where: eq(schema.flightSchools.id, schoolId),
48	    columns: {
49	      id: true,
50	      stripeConnectAccountId: true,
51	      stripeChargesEnabled: true,
52	      stripeAccountStatus: true,
53	    },
54	  });
55	  if (!row) return null;
56	  return {
57	    schoolId: row.id,
58	    stripeConnectAccountId: row.stripeConnectAccountId ?? null,
59	    chargesEnabled: row.stripeChargesEnabled === true,
60	    accountStatus: row.stripeAccountStatus ?? 'not_connected',
61	  };
62	}
63	
64	function isStripeResourceMissing(err: unknown): boolean {
65	  if (typeof err !== 'object' || err === null) return false;
66	  const rec = err as { code?: unknown; statusCode?: unknown };
67	  return rec.code === 'resource_missing' || rec.statusCode === 404;
68	}
69	
70	/**
71	 * Retrieve a Stripe customer for a given school. Tries in order:
72	 *   1. The school's Stripe Connect account via the platform Stripe client and
73	 *      required `stripeAccount` request options.
74	 *
75	 * It never falls back to Hilo's platform account or legacy OAuth/restricted-key
76	 * credentials for school-owned customer retrieval.
77	 */
78	export async function retrieveCustomerWithFallback(
79	  customerId: string,
80	  schoolId: string | null,
81	): Promise<{ customer: Stripe.Customer; stripeAccountId: string | null }> {
82	  if (!schoolId) {
83	    throw new ProvidedIdNotFoundError(customerId, null);
84	  }
85	
86	  const schoolStripe = await getSchoolStripeService(schoolId);
87	
88	  try {
89	    const schoolCustomer = await schoolStripe.retrieveCustomer(customerId);
90	    if ((schoolCustomer as { deleted?: boolean }).deleted) {
91	      throw new StripeCustomerDeletedError(customerId);
92	    }
93	    return {
94	      customer: schoolCustomer as Stripe.Customer,
95	      stripeAccountId: schoolStripe.accountId,
96	    };
97	  } catch (err: unknown) {
98	    if (err instanceof StripeCustomerDeletedError) throw err;
99	    if (err instanceof ProvidedIdNotFoundError) throw err;
100	    if (isStripeResourceMissing(err)) {
101	      throw new ProvidedIdNotFoundError(customerId, schoolStripe.accountId);
102	    }
103	    throw err;
104	  }
105	}
