90	/** Build a candidate summary with activity signals so the admin can judge match quality. */
91	async function buildCandidateSummary(
92	  customer: Stripe.Customer,
93	  stripeAccount: string,
94	  client: Stripe,
95	  matchContext: StudentMatchContext = {},
96	): Promise<CandidateSummary> {
97	  let totalSpentCents = 0;
98	  let recentTransactions: RecentStripeTransaction[] = [];
99	  try {
100	    // Lifetime spend on succeeded charges. Paginated list would be more accurate
101	    // but the first 100 covers >99% of practical cases and keeps the admin flow fast.
102	    const charges = await stripeBreaker.execute(() =>
103	      client.charges.list(
104	        { customer: customer.id, limit: 100 },
105	        { stripeAccount },
106	      ),
107	    );
108	    totalSpentCents = charges.data
109	      .filter((ch) => ch.status === 'succeeded' && !ch.refunded)
110	      .reduce((sum, ch) => sum + (ch.amount ?? 0), 0);
111	    recentTransactions = charges.data.slice(0, 3).map((ch) => ({
112	      id: ch.id,
113	      amount: ch.amount ?? 0,
114	      currency: ch.currency ?? 'usd',
115	      status: ch.status,
116	      created: ch.created,
117	      description: ch.description ?? null,
118	      refunded: Boolean(ch.refunded),
119	    }));
120	  } catch {
121	    // Non-fatal; UI tolerates missing signal.
122	  }
123	
124	  const invoiceSettings = customer.invoice_settings as
125	    | { default_payment_method?: string | null }
126	    | undefined;
127	  const hasDefaultPaymentMethod =
128	    invoiceSettings?.default_payment_method != null;
129	
130	  const meta = customer.metadata as Record<string, string> | null | undefined;
131	  const hiloStudentId = meta?.hilo_student_id ?? meta?.studentId ?? null;
132	  const confidence = scoreCustomerCandidate({
133	    customer,
134	    matchContext,
135	    hiloStudentId,
136	    hasDefaultPaymentMethod,
137	    totalSpentCents,
138	  });
139	
140	  return {
141	    id: customer.id,
142	    name: customer.name ?? null,
143	    email: customer.email ?? null,
144	    phone: customer.phone ?? null,
145	    created: customer.created,
146	    totalSpentCents,
147	    hasDefaultPaymentMethod,
148	    hiloStudentId,
149	    confidenceScore: confidence.score,
150	    confidenceLabel:
151	      confidence.score >= 80
152	        ? 'high'
153	        : confidence.score >= 55
154	          ? 'medium'
155	          : 'low',
156	    matchReasons: confidence.reasons,
157	    recentTransactions,
158	  };
159	}
