161	function scoreCustomerCandidate(args: {
162	  customer: Stripe.Customer;
163	  matchContext: StudentMatchContext;
164	  hiloStudentId: string | null;
165	  hasDefaultPaymentMethod: boolean;
166	  totalSpentCents: number;
167	}): { score: number; reasons: string[] } {
168	  const reasons: string[] = [];
169	  let score = 0;
170	
171	  if (
172	    args.matchContext.studentId &&
173	    args.hiloStudentId === args.matchContext.studentId
174	  ) {
175	    score += 50;
176	    reasons.push('Hilo student metadata match');
177	  }
178	
179	  if (
180	    args.customer.email &&
181	    args.matchContext.email &&
182	    normalizeEmail(args.customer.email) ===
183	      normalizeEmail(args.matchContext.email)
184	  ) {
185	    score = 100;
186	    reasons.push('Email match');
187	  }
188	
189	  if (
190	    args.customer.phone &&
191	    args.matchContext.phone &&
192	    normalizePhone(args.customer.phone) ===
193	      normalizePhone(args.matchContext.phone)
194	  ) {
195	    score += 20;
196	    reasons.push('Phone match');
197	  }
198	
199	  const customerName = normalizeName(args.customer.name);
200	  const studentName = normalizeName(args.matchContext.name);
201	  if (customerName && studentName) {
202	    if (customerName === studentName) {
203	      score += 20;
204	      reasons.push('Name match');
205	    } else if (
206	      customerName.includes(studentName) ||
207	      studentName.includes(customerName)
208	    ) {
209	      score += 10;
210	      reasons.push('Similar name');
211	    }
212	  }
213	
214	  if (args.hasDefaultPaymentMethod) {
215	    score += 8;
216	    reasons.push('Default payment method');
217	  }
218	
219	  if (args.totalSpentCents > 0) {
220	    score += 7;
221	    reasons.push('Stripe transaction history');
222	  }
223	
224	  return { score: Math.min(score, 100), reasons };
225	}
