227	function normalizeEmail(value: string): string {
228	  return value.trim().toLowerCase();
229	}
230	
231	function normalizePhone(value: string): string {
232	  return value.replace(/\D/g, '');
233	}
234	
235	function normalizeName(value: string | null | undefined): string {
236	  return (value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
237	}
