239	/**
240	 * Search for customers matching the student on email OR name in the school's
241	 * Connect account. Callers must pass a Connect-scoped client and account id;
242	 * normal school customer lookup must never fall back to Hilo's platform account.
243	 */
244	async function findCandidateCustomers(args: {
245	  email: string | null;
246	  name: string | null;
247	  excludeId?: string | null;
248	  limit?: number;
249	  stripeAccount: string;
250	  client: Stripe;
251	  studentId?: string | null;
252	  phone?: string | null;
253	  failOnSearchError?: boolean;
254	}): Promise<CandidateSummary[]> {
255	  const {
256	    email,
257	    name,
258	    excludeId,
259	    limit = 5,
260	    stripeAccount,
261	    client,
262	    studentId,
263	    phone,
264	    failOnSearchError = false,
265	  } = args;
266	  const options = { stripeAccount };
267	  const promises: Promise<{ data: Stripe.Customer[] }>[] = [];
268	
269	  if (email) {
270	    promises.push(
271	      stripeBreaker.execute(() =>
272	        client.customers.list({ email, limit }, options),
273	      ),
274	    );
275	  }
276	  if (name && name.trim().length >= 3) {
277	    const safeName = name.replace(/"/g, '');
278	    promises.push(
279	      stripeBreaker.execute(() =>
280	        client.customers.search(
281	          { query: `name~"${safeName}"`, limit },
282	          options,
283	        ),
284	      ),
285	    );
286	  }
287	
288	  if (promises.length === 0) return [];
289	
290	  const results = await Promise.allSettled(promises);
291	  if (failOnSearchError) {
292	    const rejected = results.find((r) => r.status === 'rejected');
293	    if (rejected?.status === 'rejected') throw rejected.reason;
294	  }
295	
296	  const seen = new Set<string>();
297	  const customers: Stripe.Customer[] = [];
298	  for (const r of results) {
299	    if (r.status !== 'fulfilled') continue;
300	    for (const c of r.value.data) {
301	      if (excludeId && c.id === excludeId) continue;
302	      if (seen.has(c.id)) continue;
303	      seen.add(c.id);
304	      customers.push(c);
305	    }
306	  }
307	
308	  const summaries = await Promise.all(
309	    customers.map((cust) =>
310	      buildCandidateSummary(cust, stripeAccount, client, {
311	        studentId,
312	        email,
313	        name,
314	        phone,
315	      }),
316	    ),
317	  );
318	  return summaries.sort(
319	    (a, b) =>
320	      b.confidenceScore - a.confidenceScore ||
321	      b.totalSpentCents - a.totalSpentCents ||
322	      b.created - a.created,
323	  );
324	}
