470	/**
471	 * Create a SetupIntent for saving a card on file.
472	 *
473	 * Auto-creation of Stripe customers from this route is banned (see PDD-006).
474	 * If the student has no mapping, return 409 NO_STRIPE_CUSTOMER so the frontend
475	 * can direct the admin to explicitly link/create via POST /stripe/customers/sync.
476	 *
477	 * Background: on 2026-04-20 the previous auto-create path silently created an
478	 * orphan customer on Hilo's platform account for a student whose real customer
479	 * lived on the school's own Stripe account — hiding $17K of prior history and
480	 * sending $765 to the wrong ledger.
481	 *
482	 * Tenant-guarded: the caller's session school must match the student's
483	 * flightSchoolId, or the request 404s. studentId comes from the request body,
484	 * so without this check any authenticated user could mint a SetupIntent
485	 * clientSecret for another tenant's student.
486	 */
487	stripe.post('/create-setup-intent', requireAuth(), async (c) => {
488	  try {
489	    const {
490	      studentId,
491	    }: {
492	      studentId: string;
493	    } = await c.req.json();
494	
495	    if (!studentId) {
496	      return c.json(
497	        {
498	          error:
499	            'studentId is required. Admin must link this student to a Stripe customer before cards can be added.',
500	          code: 'NO_STRIPE_CUSTOMER',
501	        },
502	        409,
503	      );
504	    }
505	
506	    const user = await db.query.users.findFirst({
507	      where: eq(schema.users.id, studentId),
508	      columns: {
509	        id: true,
510	        stripeCustomerId: true,
511	        stripeSource: true,
512	        stripeAccountId: true,
513	        flightSchoolId: true,
514	      },
515	    });
516	
517	    // Tenant isolation: only students in the caller's own flight school (or
518	    // the school a super-admin is managing via X-Managed-School-Id, handled
519	    // inside resolveOrgIdFromSession). 404 — not 403 — so a cross-tenant
520	    // probe cannot confirm the student exists; runs before the mapping checks
521	    // below so it also cannot learn the student's Stripe mapping state.
522	    // Mirrors the guard in src/server/api/v1/routes/payments.create.ts.
523	    if (!user) {
524	      return c.json({ error: 'Student not found' }, 404);
525	    }
526	    const access = await ensureStudentFlightSchoolAccess(c, user);
527	    if (!access.allowed) return c.json(access.body, access.status);
528	
529	    if (!user.stripeCustomerId) {
530	      return c.json(
531	        {
532	          error:
533	            'No Stripe customer is linked to this student. An admin must link an existing Stripe customer or create one via the Stripe Customer Mapping drawer before cards can be added.',
534	          code: 'NO_STRIPE_CUSTOMER',
535	        },
536	        409,
537	      );
538	    }
539	
540	    // Mappings created by the legacy auto-create path are untrusted until an
541	    // admin re-validates them — block Add Card until someone confirms the
542	    // mapping is correct via the drawer.
543	    if (user.stripeSource === 'auto_setup_intent') {
544	      return c.json(
545	        {
546	          error:
547	            'This student was mapped by a legacy auto-create path and must be re-validated by an admin before additional cards can be added.',
548	          code: 'STRIPE_MAPPING_UNVERIFIED',
549	        },
550	        409,
551	      );
552	    }
553	
554	    const schoolStripe = await getSchoolStripeService(access.flightSchoolId);
555	    try {
556	      schoolStripe.assertCustomerBoundary(user.stripeAccountId);
557	    } catch (err) {
558	      if (err instanceof SchoolStripeServiceError) {
559	        return c.json(
560	          {
561	            code: err.code,
562	            error: err.message,
563	            expectedAccountId: schoolStripe.accountId,
564	            mappedAccountId: user.stripeAccountId ?? null,
565	          },
566	          409,
567	        );
568	      }
569	      throw err;
570	    }
571	
572	    try {
573	      await schoolStripe.retrieveCustomer(user.stripeCustomerId);
574	    } catch (err: unknown) {
575	      if (
576	        err instanceof SchoolStripeServiceError &&
577	        err.code === 'STRIPE_CUSTOMER_DELETED'
578	      ) {
579	        return c.json(
580	          {
581	            error:
582	              'The Stripe customer linked to this student has been deleted. An admin must re-link via the Stripe Customer Mapping drawer.',
583	            code: 'STRIPE_CUSTOMER_DELETED',
584	          },
585	          409,
586	        );
587	      }
588	      throw err;
589	    }
590	
591	    const setupIntent = await schoolStripe.createSetupIntent(
592	      user.stripeCustomerId,
593	    );
594	
595	    return c.json({
596	      clientSecret: setupIntent.client_secret,
597	      customerId: user.stripeCustomerId,
598	      stripeAccountId: schoolStripe.accountId,
599	    });
600	  } catch (e: unknown) {
601	    if (e instanceof CircuitOpenError) {
602	      return c.json({ error: 'Stripe service temporarily unavailable' }, 503);
603	    }
604	    if (e instanceof SchoolStripeServiceError) {
605	      return c.json({ error: e.message, code: e.code }, 409);
606	    }
607	    const msg = extractError(e);
608	    console.error('[Stripe] SetupIntent error:', e);
609	    return c.json({ error: msg }, 502);
610	  }
611	});
