18	/**
19	 * Stripe Webhook Endpoint
20	 *
21	 * Receives webhook events from Stripe, verifies the signature, logs them
22	 * for idempotency, and dispatches processing.
23	 *
24	 * Stripe webhook setup:
25	 *   - URL: https://app.hilo.ai/api/stripe-webhook
26	 *   - Events: setup_intent.succeeded, payment_intent.succeeded,
27	 *             payment_intent.payment_failed, account.application.deauthorized,
28	 *             charge.dispute.created
29	 *
30	 * Required env vars:
31	 *   - STRIPE_SECRET_KEY
32	 *   - STRIPE_WEBHOOK_SECRET
33	 */
34	import { type NextRequest, NextResponse } from 'next/server';
35	import Stripe from 'stripe';
36	
37	const HILO_PLATFORM_OWNER_ID =
38	  process.env.HILO_PLATFORM_OWNER_ID ?? 'hilo-platform';
39	const HILO_STRIPE_PROVIDER_ACCOUNT_ID =
40	  process.env.HILO_STRIPE_ACCOUNT_ID ?? 'platform';
41	
42	type StripeWebhookOwnerScope = {
43	  ownerType: 'HILO_PLATFORM' | 'FLIGHT_SCHOOL';
44	  ownerId: string;
45	  providerAccountId: string;
46	};
47	
48	export async function POST(request: NextRequest) {
49	  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;
50	  if (!webhookSecret) {
51	    console.error('[Stripe Webhook] STRIPE_WEBHOOK_SECRET not configured');
52	    return NextResponse.json(
53	      { error: 'Webhook secret not configured' },
54	      { status: 500 },
55	    );
56	  }
57	
58	  // Must read raw body for signature verification (NOT .json())
59	  const rawBody = await request.text();
60	  const signature = request.headers.get('stripe-signature');
61	  if (!signature) {
62	    return NextResponse.json(
63	      { error: 'Missing stripe-signature header' },
64	      { status: 400 },
65	    );
66	  }
67	
68	  let event: Stripe.Event;
69	  try {
70	    event = Stripe.webhooks.constructEvent(rawBody, signature, webhookSecret);
71	  } catch (err) {
72	    const msg = err instanceof Error ? err.message : 'Unknown error';
73	    console.error('[Stripe Webhook] Signature verification failed:', msg);
74	    return NextResponse.json({ error: 'Invalid signature' }, { status: 401 });
75	  }
76	
77	  const ownerScope = await resolveStripeWebhookOwnerScope(event);
78	  const idempotencyKey = [
79	    'STRIPE',
80	    ownerScope.ownerType,
81	    ownerScope.ownerId,
82	    ownerScope.providerAccountId,
83	    event.id,
84	  ].join('|');
85	  const preExisting = await findExistingStripeWebhookReceipt(
86	    ownerScope,
87	    event.id,
88	  );
89	  if (preExisting?.status === 'processed') {
90	    return NextResponse.json({ status: 'already_processed' });
91	  }
92	
93	  const inserted = await insertStripeWebhookReceipt({
94	    event,
95	    ownerScope,
96	    idempotencyKey,
97	  });
98	
99	  if (inserted.length === 0) {
100	    const existing = await findExistingStripeWebhookReceipt(
101	      ownerScope,
102	      event.id,
103	    );
104	    if (existing?.status === 'processed') {
105	      return NextResponse.json({ status: 'already_processed' });
106	    }
107	    if (existing?.status !== 'failed') {
108	      return NextResponse.json({ status: 'duplicate_in_flight' });
109	    }
110	  }
111	
112	  // Process the event — return 200 quickly, log errors
113	  try {
114	    await processEvent(event);
115	
116	    await db
117	      .update(schema.stripeWebhookEvents)
118	      .set({ status: 'processed', processedAt: new Date() })
119	      .where(stripeWebhookEventWhere(ownerScope, event.id));
120	  } catch (err) {
121	    const msg = err instanceof Error ? err.message : 'Unknown error';
122	    console.error(`[Stripe Webhook] Processing error for ${event.type}:`, msg);
123	
124	    await db
125	      .update(schema.stripeWebhookEvents)
126	      .set({ status: 'failed', error: msg })
127	      .where(stripeWebhookEventWhere(ownerScope, event.id));
128	  }
129	
130	  return NextResponse.json({ status: 'ok', event_type: event.type });
131	}
