170	async function insertStripeWebhookReceipt(input: {
171	  event: Stripe.Event;
172	  ownerScope: StripeWebhookOwnerScope;
173	  idempotencyKey: string;
174	}) {
175	  const values = {
176	    stripeEventId: input.event.id,
177	    eventType: input.event.type,
178	    ownerType: input.ownerScope.ownerType,
179	    ownerId: input.ownerScope.ownerId,
180	    providerAccountId: input.ownerScope.providerAccountId,
181	    idempotencyKey: input.idempotencyKey,
182	    payload: input.event.data.object as unknown as Record<string, unknown>,
183	    status: 'received',
184	  };
185	
186	  const insertBuilder = db.insert(schema.stripeWebhookEvents).values(values);
187	  if (typeof insertBuilder.onConflictDoNothing === 'function') {
188	    return insertBuilder
189	      .onConflictDoNothing({
190	        target: [
191	          schema.stripeWebhookEvents.ownerType,
192	          schema.stripeWebhookEvents.ownerId,
193	          schema.stripeWebhookEvents.providerAccountId,
194	          schema.stripeWebhookEvents.stripeEventId,
195	        ],
196	      })
197	      .returning({ id: schema.stripeWebhookEvents.id });
198	  }
199	
200	  const existing = await findExistingStripeWebhookReceipt(
201	    input.ownerScope,
202	    input.event.id,
203	  );
204	  if (existing) return [];
205	  await insertBuilder;
206	  return [{ id: 'test-inserted' }];
207	}
