243	async function processEvent(event: Stripe.Event) {
244	  const stripeAccountId = event.account ?? null;
245	  switch (event.type) {
246	    case 'setup_intent.succeeded':
247	      await handleSetupIntentSucceeded(
248	        event.data.object as Stripe.SetupIntent,
249	        stripeAccountId,
250	      );
251	      break;
252	
253	    case 'setup_intent.setup_failed':
254	      await handleSetupIntentFailed(
255	        event.data.object as Stripe.SetupIntent,
256	        stripeAccountId,
257	      );
258	      break;
259	
260	    case 'payment_intent.processing':
261	      await handlePaymentIntentProcessing(
262	        event.data.object as Stripe.PaymentIntent,
263	        stripeAccountId,
264	      );
265	      break;
266	
267	    case 'payment_intent.succeeded':
268	      await handlePaymentIntentSucceeded(
269	        event.data.object as Stripe.PaymentIntent,
270	        stripeAccountId,
271	      );
272	      break;
273	
274	    case 'payment_intent.payment_failed':
275	      await handlePaymentIntentFailed(
276	        event.data.object as Stripe.PaymentIntent,
277	        stripeAccountId,
278	      );
279	      break;
280	
281	    // Connected-account state changes — sync the school's stripe_charges_enabled
282	    // / stripe_account_status cache so billing routes gate correctly without an
283	    // extra Stripe API call. The 2026-04-24 incident root cause was a stale
284	    // pending-account state going un-noticed.
285	    case 'account.updated':
286	      await handleAccountUpdated(event.data.object as Stripe.Account);
287	      break;
288	
289	    // Customer mirror updates — keep ATOS user.email in sync with Stripe
290	    // customer.email so the next reconciliation sweep doesn't flag a false
291	    // mismatch.
292	    case 'customer.updated':
293	      await handleCustomerUpdated(
294	        event.data.object as Stripe.Customer,
295	        stripeAccountId,
296	      );
297	      break;
298	
299	    // Hard delete on Stripe's side — null out the mapping and queue an admin
300	    // re-link via a pending reconciliation row.
301	    case 'customer.deleted':
302	      await handleCustomerDeleted(
303	        event.data.object as Stripe.Customer | Stripe.DeletedCustomer,
304	        stripeAccountId,
305	      );
306	      break;
307	
308	    case 'account.application.deauthorized':
309	      await handleAccountDeauthorized(
310	        event.data.object as Stripe.Application,
311	        event.account,
312	      );
313	      break;
314	
315	    case 'charge.dispute.created':
316	      await handleDisputeCreated(
317	        event.data.object as Stripe.Dispute,
318	        stripeAccountId,
319	      );
320	      break;
321	
322	    case 'payment_method.automatically_updated':
323	      await handlePaymentMethodAutomaticallyUpdated(
324	        event.data.object as Stripe.PaymentMethod,
325	        event.data.previous_attributes as Record<string, unknown> | undefined,
326	      );
327	      break;
328	
329	    case 'invoice.paid':
330	      await handleInvoicePaid(event.data.object as Stripe.Invoice);
331	      break;
332	
333	    case 'invoice.payment_failed':
334	      await handleInvoicePaymentFailed(event.data.object as Stripe.Invoice);
335	      break;
336	
337	    case 'invoice.finalized':
338	      await handleInvoiceFinalized(event.data.object as Stripe.Invoice);
339	      break;
340	
341	    case 'invoice.created': {
342	      const createdInvoice = event.data.object as Stripe.Invoice;
343	      console.log(`[Stripe Webhook] Invoice created: ${createdInvoice.id}`);
344	      // Ensure a local record exists (covers invoices created outside the cron)
345	      await ensureLocalInvoice(createdInvoice);
346	      // Sync to QuickBooks (fire-and-forget)
347	      onInvoiceCreated(createdInvoice.id).catch((err) => {
348	        console.error(
349	          '[Stripe Webhook] QB sync on invoice created failed:',
350	          err,
351	        );
352	      });
353	      break;
354	    }
355	
356	    default:
357	      console.log(`[Stripe Webhook] Unhandled event type: ${event.type}`);
358	  }
359	}
