391	/**
392	 * When a SetupIntent succeeds, retrieve the payment method details
393	 * and store them in the appropriate table.
394	 */
395	async function handleSetupIntentSucceeded(
396	  setupIntent: Stripe.SetupIntent,
397	  stripeAccountId: string | null,
398	) {
399	  const customerId =
400	    typeof setupIntent.customer === 'string'
401	      ? setupIntent.customer
402	      : setupIntent.customer?.id;
403	  const pmId =
404	    typeof setupIntent.payment_method === 'string'
405	      ? setupIntent.payment_method
406	      : setupIntent.payment_method?.id;
407	
408	  if (!pmId) {
409	    console.warn(
410	      '[Stripe Webhook] SetupIntent succeeded without payment_method',
411	    );
412	    return;
413	  }
414	
415	  // Retrieve full payment method details server-side
416	  const pm = stripeAccountId
417	    ? await stripeClient.paymentMethods.retrieve(
418	        pmId,
419	        {},
420	        {
421	          stripeAccount: stripeAccountId,
422	        },
423	      )
424	    : await stripeClient.paymentMethods.retrieve(pmId);
425	
426	  let brand = 'Card';
427	  let last4 = '0000';
428	  let expiry: string | undefined;
429	  let funding: string | undefined;
430	  let cardholderName: string | undefined;
431	
432	  if (pm.card) {
433	    brand = pm.card.brand
434	      ? `${pm.card.brand.charAt(0).toUpperCase()}${pm.card.brand.slice(1)}`
435	      : 'Card';
436	    last4 = pm.card.last4 || '0000';
437	    expiry =
438	      pm.card.exp_month && pm.card.exp_year
439	        ? `${String(pm.card.exp_month).padStart(2, '0')}/${String(pm.card.exp_year).slice(-2)}`
440	        : undefined;
441	    funding = pm.card.funding || undefined;
442	  } else if (pm.us_bank_account) {
443	    brand = pm.us_bank_account.bank_name || 'Bank account';
444	    last4 = pm.us_bank_account.last4 || '0000';
445	    funding = 'us_bank_account';
446	  }
447	  if (typeof pm.billing_details?.name === 'string') {
448	    cardholderName = pm.billing_details.name;
449	  }
450	
451	  // Determine if this is a school or student customer
452	  if (customerId) {
453	    // Check if this is a school billing customer
454	    const billingConfig = await db.query.billingConfig.findFirst({
455	      where: eq(schema.billingConfig.stripeCustomerId, customerId),
456	    });
457	
458	    if (billingConfig) {
459	      // School payment method — upsert to avoid duplicates
460	      const existingPm = await db.query.schoolPaymentMethods.findFirst({
461	        where: and(
462	          eq(
463	            schema.schoolPaymentMethods.flightSchoolId,
464	            billingConfig.flightSchoolId,
465	          ),
466	          eq(schema.schoolPaymentMethods.stripePaymentMethodId, pmId),
467	        ),
468	      });
469	
470	      if (!existingPm) {
471	        const existingMethods = await db.query.schoolPaymentMethods.findMany({
472	          where: eq(
473	            schema.schoolPaymentMethods.flightSchoolId,
474	            billingConfig.flightSchoolId,
475	          ),
476	        });
477	        await db.insert(schema.schoolPaymentMethods).values({
478	          flightSchoolId: billingConfig.flightSchoolId,
479	          stripePaymentMethodId: pmId,
480	          brand,
481	          last4,
482	          expiry,
483	          funding,
484	          cardholderName,
485	          isDefault: existingMethods.length === 0,
486	        });
487	      }
488	    }
489	
490	    // Check if this is a student customer
491	    const user = await db.query.users.findFirst({
492	      where: userStripeCustomerWhere(customerId, stripeAccountId),
493	    });
494	
495	    if (user) {
496	      // Log for audit — student card saved via webhook
497	      await db.insert(schema.auditLogs).values({
498	        flightSchoolId: user.flightSchoolId,
499	        studentId: user.id,
500	        userName: 'System (Stripe Webhook)',
501	        userEmail: 'stripe@system',
502	        action: 'payment_method_saved',
503	        category: 'payment',
504	        resource: 'stripe',
505	        details: `Payment method ${brand} ending ${last4} confirmed via webhook for student ${user.name}`,
506	      });
507	    }
508	  }
509	
510	  console.log(
511	    `[Stripe Webhook] SetupIntent succeeded: PM ${pmId} (${brand} ...${last4}) for customer ${customerId}`,
512	  );
513	}
