586	/**
587	 * When a PaymentIntent succeeds, update the matching history row to completed
588	 * and mark the invoice as Completed (handles ACH settlement confirmation and
589	 * also fires for card PIs created outside the charge endpoint).
590	 */
591	
592	async function handlePaymentIntentSucceeded(
593	  paymentIntent: Stripe.PaymentIntent,
594	  stripeAccountId: string | null,
595	) {
596	  // TD-2: signup onboarding charges carry metadata.signupId and have no
597	  // customer, so they match no student_payment_history row and the path below
598	  // would no-op on them. This branch records the payment against the signup and
599	  // returns.
600	  //
601	  // Note it writes no ledger entry either — signup revenue still does not reach
602	  // `invoices` or QuickBooks. Booking it needs the tenant that the signup has
603	  // not been provisioned into yet, so it is deliberately out of scope here.
604	  const signupId = paymentIntent.metadata?.signupId;
605	
606	  if (signupId && stripeAccountId) {
607	    // Signup PaymentIntents are platform objects by construction — the signup
608	    // flow is pre-tenant (schema/signups.ts: flightSchoolId is nullable, the row
609	    // predates any school). A signupId on a connected-account event is therefore
610	    // never legitimate: it means a school created a PaymentIntent on its own
611	    // account carrying forged metadata. Fall through and let the normal
612	    // student-payment path below handle it as the connected-account payment it
613	    // actually is; matching on studentPaymentHistory no-ops if nothing matches.
614	    console.warn(
615	      `[Stripe Webhook] Ignoring signupId metadata on connected-account event: signupId=${signupId} account=${stripeAccountId} pi=${paymentIntent.id}`,
616	    );
617	  } else if (signupId) {
618	    // `ne(status, 'completed')` keeps the transition monotonic. The lifecycle is
619	    // pending -> paid -> completed, and this delivery can land *after*
620	    // /api/signup/complete has provisioned the tenant (Stripe retries, or plain
621	    // ordering). Without the predicate that write regresses 'completed' back to
622	    // 'paid', disarming the `status === 'completed'` guard in both signup routes
623	    // and turning a benign double-submit 409 into a 500. The event-level
624	    // idempotency ledger above does not cover this: it is keyed on event.id, and
625	    // a redelivery for the same object carries a different id.
626	    await db
627	      .update(signups)
628	      .set({ status: 'paid' })
629	      .where(and(eq(signups.id, signupId), ne(signups.status, 'completed')));
630	
631	    console.log(
632	      `[Stripe Webhook] Signup payment recorded: signupId=${signupId} amount=${paymentIntent.amount_received}`,
633	    );
634	
635	    return;
636	  }
637	
638	  const piId = paymentIntent.id;
639	  const customerId =
640	    typeof paymentIntent.customer === 'string'
641	      ? paymentIntent.customer
642	      : paymentIntent.customer?.id;
643	
644	  console.log(
645	    `[Stripe Webhook] PaymentIntent succeeded: ${piId} ($${(paymentIntent.amount / 100).toFixed(2)})`,
646	  );
647	
648	  // Update payment history row if it exists (created by charge-card route).
649	  // Idempotent: if already completed, the SET is a no-op but RETURNING still fires.
650	  const [updatedRow] = await db
651	    .update(schema.studentPaymentHistory)
652	    .set({
653	      status: 'completed',
654	      paymentDate: new Date(),
655	    })
656	    .where(paymentHistoryStripePaymentIntentWhere(piId, stripeAccountId))
657	    .returning({
658	      id: schema.studentPaymentHistory.id,
659	      invoiceId: schema.studentPaymentHistory.invoiceId,
660	      studentId: schema.studentPaymentHistory.studentId,
661	      flightSchoolId: schema.studentPaymentHistory.flightSchoolId,
662	      locationId: schema.studentPaymentHistory.locationId,
663	      paymentMethodType: schema.studentPaymentHistory.paymentMethodType,
664	      amount: schema.studentPaymentHistory.amount,
665	      balanceDelta: schema.studentPaymentHistory.balanceDelta,
666	    });
667	
668	  if (updatedRow?.invoiceId) {
669	    const [linkedInvoice] = await db
670	      .select({
671	        amount: schema.studentInvoices.amount,
672	        metadata: schema.studentInvoices.metadata,
673	      })
674	      .from(schema.studentInvoices)
675	      .where(eq(schema.studentInvoices.id, updatedRow.invoiceId))
676	      .limit(1);
677	    const isPrepaidTrainingPurchase =
678	      linkedInvoice &&
679	      isPrepaidTrainingPurchaseMetadata(linkedInvoice.metadata);
680	    const targetBalanceDelta = isPrepaidTrainingPurchase
681	      ? getPrepaidPurchaseBalanceCreditCents(
682	          linkedInvoice.metadata,
683	          linkedInvoice.amount,
684	        )
685	      : updatedRow.amount;
686	
687	    // For ACH settlement: apply the balance delta now that the transfer settled.
688	    // The charge route held balanceDelta at 0 while status was 'processing'.
689	    if (
690	      updatedRow.paymentMethodType === 'us_bank_account' &&
691	      updatedRow.studentId
692	    ) {
693	      const unappliedBalanceDelta =
694	        targetBalanceDelta - (updatedRow.balanceDelta ?? 0);
695	      if (unappliedBalanceDelta !== 0) {
696	        await db
697	          .update(schema.users)
698	          .set({
699	            balance: sql`COALESCE(balance, 0) + ${(unappliedBalanceDelta / 100).toFixed(4)}`,
700	            updatedAt: new Date(),
701	          })
702	          .where(eq(schema.users.id, updatedRow.studentId));
703	      }
704	    }
705	
706	    await db
707	      .update(schema.studentPaymentHistory)
708	      .set({ balanceDelta: targetBalanceDelta })
709	      .where(eq(schema.studentPaymentHistory.id, updatedRow.id));
710	
711	    await db
712	      .update(schema.studentInvoices)
713	      .set({ status: 'Completed', paidAt: new Date(), updatedAt: new Date() })
714	      .where(eq(schema.studentInvoices.id, updatedRow.invoiceId));
715	
716	    if (
717	      isPrepaidTrainingPurchase &&
718	      updatedRow.flightSchoolId &&
719	      updatedRow.locationId &&
720	      updatedRow.studentId
721	    ) {
722	      await finalizePrepaidHourAllocation({
723	        orgId: updatedRow.flightSchoolId,
724	        locationId: updatedRow.locationId,
725	        studentId: updatedRow.studentId,
726	        invoiceId: updatedRow.invoiceId,
727	      });
728	      if (getPrepaidAccountBalanceSettlementCents(linkedInvoice.metadata) > 0) {
729	        await autoApplyBalanceToInvoices(
730	          updatedRow.flightSchoolId,
731	          updatedRow.locationId,
732	          updatedRow.studentId,
733	        );
734	      }
735	    }
736	  }
737	
738	  // Audit log
739	  if (customerId) {
740	    const user = await db.query.users.findFirst({
741	      where: userStripeCustomerWhere(customerId, stripeAccountId),
742	    });
743	    if (user) {
744	      await db.insert(schema.auditLogs).values({
745	        flightSchoolId: user.flightSchoolId,
746	        studentId: user.id,
747	        userName: 'System (Stripe Webhook)',
748	        userEmail: 'stripe@system',
749	        action: 'payment_succeeded',
750	        category: 'payment',
751	        resource: 'stripe',
752	        details: `Payment of $${(paymentIntent.amount / 100).toFixed(2)} ${paymentIntent.currency.toUpperCase()} succeeded (${piId})`,
753	      });
754	    }
755	  }
756	}
