758	/**
759	 * When a PaymentIntent fails, update the history row with the failure code
760	 * and reset the invoice status for retry (ACH returns like R01/R10 allow retry).
761	 */
762	async function handlePaymentIntentFailed(
763	  paymentIntent: Stripe.PaymentIntent,
764	  stripeAccountId: string | null,
765	) {
766	  const piId = paymentIntent.id;
767	  const customerId =
768	    typeof paymentIntent.customer === 'string'
769	      ? paymentIntent.customer
770	      : paymentIntent.customer?.id;
771	  const lastError = paymentIntent.last_payment_error;
772	  const errorMessage = lastError?.message ?? 'Unknown payment failure';
773	  // ACH return codes come through in decline_code (e.g. 'R01', 'R10')
774	  const failureCode = lastError?.decline_code ?? lastError?.code ?? null;
775	
776	  console.error(
777	    `[Stripe Webhook] PaymentIntent failed: ${piId} — ${errorMessage} (code: ${failureCode ?? 'n/a'})`,
778	  );
779	
780	  // Update matching history row
781	  const [updatedRow] = await db
782	    .update(schema.studentPaymentHistory)
783	    .set({
784	      status: 'failed',
785	      failureCode,
786	    })
787	    .where(paymentHistoryStripePaymentIntentWhere(piId, stripeAccountId))
788	    .returning({
789	      id: schema.studentPaymentHistory.id,
790	      invoiceId: schema.studentPaymentHistory.invoiceId,
791	      paymentMethodType: schema.studentPaymentHistory.paymentMethodType,
792	    });
793	
794	  if (updatedRow?.invoiceId) {
795	    // For ACH failures, reset the invoice to 'pending' so the admin can retry
796	    // (ACH return codes R01/R10/etc. mean the debit bounced; a new charge is needed)
797	    const newInvoiceStatus =
798	      updatedRow.paymentMethodType === 'us_bank_account'
799	        ? 'pending'
800	        : undefined; // card failures leave invoice in its current state
801	
802	    if (newInvoiceStatus) {
803	      await db
804	        .update(schema.studentInvoices)
805	        .set({ status: newInvoiceStatus, updatedAt: new Date() })
806	        .where(eq(schema.studentInvoices.id, updatedRow.invoiceId));
807	    }
808	  }
809	
810	  // Audit log
811	  if (customerId) {
812	    const user = await db.query.users.findFirst({
813	      where: userStripeCustomerWhere(customerId, stripeAccountId),
814	    });
815	    if (user) {
816	      await db.insert(schema.auditLogs).values({
817	        flightSchoolId: user.flightSchoolId,
818	        studentId: user.id,
819	        userName: 'System (Stripe Webhook)',
820	        userEmail: 'stripe@system',
821	        action: 'payment_failed',
822	        category: 'payment',
823	        resource: 'stripe',
824	        details: `Payment of $${(paymentIntent.amount / 100).toFixed(2)} failed: ${errorMessage} (${piId}) code=${failureCode ?? 'n/a'}`,
825	        severity: 'warning',
826	      });
827	    }
828	  }
829	}
