871	/**
872	 * When a dispute is created, log it as a high-severity audit event,
873	 * block the payment method, and set the invoice to 'disputed'.
874	 */
875	async function handleDisputeCreated(
876	  dispute: Stripe.Dispute,
877	  stripeAccountId: string | null,
878	) {
879	  const chargeId =
880	    typeof dispute.charge === 'string' ? dispute.charge : dispute.charge?.id;
881	  const piId =
882	    typeof dispute.payment_intent === 'string'
883	      ? dispute.payment_intent
884	      : dispute.payment_intent?.id;
885	
886	  console.error(
887	    `[Stripe Webhook] Dispute created: ${dispute.id} for charge ${chargeId} ($${(dispute.amount / 100).toFixed(2)})`,
888	  );
889	
890	  // Block the PM associated with this dispute PI (if we have a history row)
891	  let disputedInvoiceId: string | null = null;
892	  if (piId) {
893	    const [historyRow] = await db
894	      .select({
895	        invoiceId: schema.studentPaymentHistory.invoiceId,
896	        paymentMethod: schema.studentPaymentHistory.paymentMethod,
897	        stripePaymentIntentId:
898	          schema.studentPaymentHistory.stripePaymentIntentId,
899	      })
900	      .from(schema.studentPaymentHistory)
901	      .where(paymentHistoryStripePaymentIntentWhere(piId, stripeAccountId))
902	      .limit(1);
903	
904	    if (historyRow?.invoiceId) {
905	      disputedInvoiceId = historyRow.invoiceId;
906	
907	      // Block the PM row whose stripePaymentMethodId corresponds to the disputed PI
908	      // We find it via the payment_intent's payment_method field from Stripe
909	      const piPaymentMethod =
910	        typeof dispute.payment_intent === 'object' && dispute.payment_intent
911	          ? null // PaymentIntent object not expanded in dispute webhook
912	          : null;
913	      // Attempt to resolve via charge
914	      if (chargeId) {
915	        try {
916	          const { stripeClient } = await import('@/lib/stripe');
917	          const charge = await stripeClient.charges.retrieve(chargeId, {
918	            expand: ['payment_method'],
919	          });
920	          const stripePmId =
921	            typeof charge.payment_method === 'string'
922	              ? charge.payment_method
923	              : ((charge.payment_method as { id?: string } | null)?.id ?? null);
924	          if (stripePmId) {
925	            await db
926	              .update(schema.studentPaymentCards)
927	              .set({ isBlocked: true })
928	              .where(
929	                eq(
930	                  schema.studentPaymentCards.stripePaymentMethodId,
931	                  stripePmId,
932	                ),
933	              );
934	          }
935	        } catch {
936	          // Non-fatal — log but continue
937	          console.error(
938	            '[Stripe Webhook] handleDisputeCreated: failed to block PM',
939	          );
940	        }
941	      }
942	      void piPaymentMethod; // suppress unused warning
943	
944	      // Set invoice to disputed
945	      await db
946	        .update(schema.studentInvoices)
947	        .set({ status: 'disputed', updatedAt: new Date() })
948	        .where(eq(schema.studentInvoices.id, disputedInvoiceId));
949	    }
950	  }
951	
952	  await db.insert(schema.auditLogs).values({
953	    userName: 'System (Stripe Webhook)',
954	    userEmail: 'stripe@system',
955	    action: 'dispute_created',
956	    category: 'payment',
957	    resource: 'stripe',
958	    details: `Dispute ${dispute.id} created for $${(dispute.amount / 100).toFixed(2)} — reason: ${dispute.reason}${disputedInvoiceId ? ` — invoiceId: ${disputedInvoiceId}` : ''}`,
959	    severity: 'error',
960	  });
961	}
