963	/**
964	 * When Stripe automatically updates a payment method (e.g., card reissued),
965	 * block it if it was marked as blocked by the network event.
966	 * NOTE: 'blocked' is a synthetic field in Stripe's event data for network
967	 * card updates — we treat its presence as a signal to block the PM.
968	 */
969	async function handlePaymentMethodAutomaticallyUpdated(
970	  paymentMethod: Stripe.PaymentMethod,
971	  previousAttributes: Record<string, unknown> | undefined,
972	) {
973	  const pmId = paymentMethod.id;
974	  console.log(`[Stripe Webhook] payment_method.automatically_updated: ${pmId}`);
975	
976	  // Stripe sends a 'blocked' flag in the event data for some network events.
977	  // If the previous attributes indicate a block state transition, apply it.
978	  const isNowBlocked =
979	    (paymentMethod as unknown as Record<string, unknown>).blocked === true ||
980	    (previousAttributes as Record<string, unknown> | undefined)?.blocked ===
981	      false;
982	
983	  if (isNowBlocked) {
984	    await db
985	      .update(schema.studentPaymentCards)
986	      .set({ isBlocked: true })
987	      .where(eq(schema.studentPaymentCards.stripePaymentMethodId, pmId));
988	
989	    console.log(
990	      `[Stripe Webhook] PM ${pmId} blocked via automatically_updated event`,
991	    );
992	  }
993	}
