1140	/**
1141	 * Idempotent helper: ensures a local invoice record exists for a Stripe invoice.
1142	 * If the record already exists, returns its ID without modification.
1143	 * If not, resolves the flightSchoolId from invoice metadata or billingConfig
1144	 * and creates the record.
1145	 */
1146	async function ensureLocalInvoice(
1147	  invoice: Stripe.Invoice,
1148	): Promise<string | null> {
1149	  const stripeInvoiceId = invoice.id;
1150	
1151	  // Resolve flightSchoolId from Stripe customer
1152	  const customerId =
1153	    typeof invoice.customer === 'string'
1154	      ? invoice.customer
1155	      : invoice.customer?.id;
1156	  if (!customerId) {
1157	    console.warn(
1158	      `[Stripe Webhook] ensureLocalInvoice: no customer on ${stripeInvoiceId}`,
1159	    );
1160	    return null;
1161	  }
1162	
1163	  // Check metadata first (cron sets flightSchoolId in metadata)
1164	  let flightSchoolId = invoice.metadata?.flightSchoolId;
1165	
1166	  if (!flightSchoolId) {
1167	    // Fall back to billingConfig lookup
1168	    const [cfg] = await db
1169	      .select({ flightSchoolId: schema.billingConfig.flightSchoolId })
1170	      .from(schema.billingConfig)
1171	      .where(eq(schema.billingConfig.stripeCustomerId, customerId));
1172	    if (!cfg) {
1173	      console.warn(
1174	        `[Stripe Webhook] ensureLocalInvoice: no billingConfig for customer ${customerId}`,
1175	      );
1176	      return null;
1177	    }
1178	    flightSchoolId = cfg.flightSchoolId;
1179	  }
1180	
1181	  const [existing] = await db
1182	    .select({ id: schema.invoices.id })
1183	    .from(schema.invoices)
1184	    .where(
1185	      and(
1186	        eq(schema.invoices.stripeInvoiceId, stripeInvoiceId),
1187	        eq(schema.invoices.flightSchoolId, flightSchoolId),
1188	      ),
1189	    )
1190	    .limit(1);
1191	  if (existing) return existing.id;
1192	
1193	  const status =
1194	    invoice.status === 'paid'
1195	      ? 'paid'
1196	      : invoice.status === 'open'
1197	        ? 'pending'
1198	        : invoice.status === 'uncollectible' || invoice.status === 'void'
1199	          ? 'overdue'
1200	          : 'pending';
1201	
1202	  const periodStart = invoice.period_start
1203	    ? new Date(invoice.period_start * 1000)
1204	    : new Date(invoice.created * 1000);
1205	  const periodEnd = invoice.period_end
1206	    ? new Date(invoice.period_end * 1000)
1207	    : new Date(invoice.created * 1000);
1208	
1209	  const [row] = await db
1210	    .insert(schema.invoices)
1211	    .values({
1212	      flightSchoolId,
1213	      stripeInvoiceId,
1214	      amount: invoice.amount_due ?? 0,
1215	      status,
1216	      periodStart,
1217	      periodEnd,
1218	      invoiceUrl: invoice.hosted_invoice_url ?? undefined,
1219	      taxAmount:
1220	        invoice.total != null && invoice.total_excluding_tax != null
1221	          ? invoice.total - invoice.total_excluding_tax
1222	          : 0,
1223	      poeCount:
1224	        invoice.metadata?.peakPoe != null
1225	          ? Number(invoice.metadata.peakPoe)
1226	          : null,
1227	      paidAt:
1228	        invoice.status === 'paid' && invoice.status_transitions?.paid_at
1229	          ? new Date(invoice.status_transitions.paid_at * 1000)
1230	          : undefined,
1231	    })
1232	    .returning({ id: schema.invoices.id });
1233	
1234	  console.log(
1235	    `[Stripe Webhook] ensureLocalInvoice: created local record for ${stripeInvoiceId}`,
1236	  );
1237	  return row?.id ?? null;
1238	}
