1240	/**
1241	 * Mirror Stripe Connect account state onto `flight_schools` so billing routes
1242	 * can gate calls on `stripe_charges_enabled` without fetching from Stripe on
1243	 * every request. Compute the same coarse status bucket as the OAuth flow:
1244	 *   restricted → requirements.disabled_reason set
1245	 *   active     → charges_enabled === true
1246	 *   pending    → otherwise (still onboarding)
1247	 */
1248	async function handleAccountUpdated(account: Stripe.Account) {
1249	  const accountId = account.id;
1250	  const school = await db.query.flightSchools.findFirst({
1251	    where: eq(schema.flightSchools.stripeConnectAccountId, accountId),
1252	    columns: { id: true, name: true },
1253	  });
1254	  if (!school) {
1255	    console.log(
1256	      `[Stripe Webhook] account.updated for ${accountId}: no matching flight_school, skipping`,
1257	    );
1258	    return;
1259	  }
1260	
1261	  const requirements = account.requirements as
1262	    | { disabled_reason?: string | null }
1263	    | null
1264	    | undefined;
1265	  const status: 'pending' | 'active' | 'restricted' =
1266	    requirements?.disabled_reason
1267	      ? 'restricted'
1268	      : account.charges_enabled
1269	        ? 'active'
1270	        : 'pending';
1271	
1272	  await db
1273	    .update(schema.flightSchools)
1274	    .set({
1275	      stripeChargesEnabled: account.charges_enabled === true,
1276	      stripeAccountStatus: status,
1277	      updatedAt: new Date(),
1278	    })
1279	    .where(eq(schema.flightSchools.id, school.id));
1280	
1281	  console.log(
1282	    `[Stripe Webhook] account.updated: school ${school.id} → ${status} (charges_enabled=${account.charges_enabled})`,
1283	  );
1284	}
