1322	/**
1323	 * When Stripe deletes a customer, null out the user's mapping and queue a
1324	 * pending reconciliation row so the admin sees the dangling customer on the
1325	 * next reconciliation review and can decide whether to re-link or dismiss.
1326	 */
1327	async function handleCustomerDeleted(
1328	  customer: Stripe.Customer | Stripe.DeletedCustomer,
1329	  stripeAccountId: string | null,
1330	) {
1331	  const customerId = customer.id;
1332	  const user = await db.query.users.findFirst({
1333	    where: userStripeCustomerWhere(customerId, stripeAccountId),
1334	    columns: { id: true, flightSchoolId: true, email: true, name: true },
1335	  });
1336	  if (!user) {
1337	    console.log(
1338	      `[Stripe Webhook] customer.deleted ${customerId}: no matching user, skipping`,
1339	    );
1340	    return;
1341	  }
1342	
1343	  await db
1344	    .update(schema.users)
1345	    .set({
1346	      stripeCustomerId: null,
1347	      stripeAccountId: null,
1348	      stripeSyncDate: null,
1349	      stripeSource: null,
1350	      updatedAt: new Date(),
1351	    })
1352	    .where(eq(schema.users.id, user.id));
1353	
1354	  // Queue an admin review row so the deletion doesn't go un-noticed. Best-effort
1355	  // — if the table has no row yet for this customer (it shouldn't, since we
1356	  // mapped it at some point) the upsert still creates one.
1357	  try {
1358	    await db
1359	      .insert(schema.stripeReconciliation)
1360	      .values({
1361	        flightSchoolId: user.flightSchoolId,
1362	        stripeCustomerId: customerId,
1363	        stripeCustomerEmail: user.email ?? null,
1364	        stripeCustomerName: user.name ?? null,
1365	        matchedUserId: null,
1366	        matchConfidence: 'none',
1367	        status: 'pending',
1368	      })
1369	      .onConflictDoUpdate({
1370	        target: [
1371	          schema.stripeReconciliation.flightSchoolId,
1372	          schema.stripeReconciliation.stripeCustomerId,
1373	        ],
1374	        set: {
1375	          matchedUserId: null,
1376	          matchConfidence: 'none',
1377	          status: 'pending',
1378	          updatedAt: new Date(),
1379	        },
1380	      });
1381	  } catch (err) {
1382	    console.error(
1383	      '[Stripe Webhook] customer.deleted: failed to upsert reconciliation row:',
1384	      err instanceof Error ? err.message : String(err),
1385	    );
1386	  }
1387	
1388	  console.log(
1389	    `[Stripe Webhook] customer.deleted: cleared mapping for user ${user.id} (was ${customerId})`,
1390	  );
1391	}
