234	export async function getSchoolStripeService(
235	  schoolId: string | null | undefined,
236	): Promise<SchoolStripeService> {
237	  if (!schoolId) {
238	    throw new SchoolStripeServiceError(
239	      'STRIPE_NOT_CONFIGURED',
240	      'Student Stripe operations require a flight school.',
241	    );
242	  }
243	
244	  const resolved = await getStripeClientForSchool(schoolId);
245	  if (resolved.type === 'configuration_error') {
246	    if (
247	      resolved.code === 'STRIPE_CONNECT_REQUIRED' ||
248	      resolved.code === 'STRIPE_LEGACY_MODE_BLOCKED'
249	    ) {
250	      throw new SchoolStripeServiceError(resolved.code, resolved.message);
251	    }
252	    throw new SchoolStripeServiceError(
253	      'STRIPE_CREDENTIAL_INVALID',
254	      resolved.message,
255	    );
256	  }
257	  if (resolved.type !== 'school' || !resolved.stripeAccountId) {
258	    throw new SchoolStripeServiceError(
259	      'STRIPE_NOT_CONFIGURED',
260	      'This school has not configured a school-owned Stripe Connect account.',
261	    );
262	  }
263	
264	  return new DefaultSchoolStripeService(
265	    schoolId,
266	    resolved.stripeAccountId,
267	    resolved.livemode,
268	    resolved.client,
269	    resolved.requestOptions,
270	  );
271	}
