449	  async findCustomerCandidates(args: {
450	    email: string | null;
451	    name: string | null;
452	    excludeId?: string | null;
453	    limit?: number;
454	  }): Promise<Stripe.Customer[]> {
455	    const { email, name, excludeId, limit = 5 } = args;
456	    const promises: Promise<{ data: Stripe.Customer[] }>[] = [];
457	
458	    if (email) {
459	      promises.push(
460	        this.withPermissionDiagnostics(
461	          'customers.list',
462	          ['customer_read'],
463	          () =>
464	            stripeBreaker.execute(() =>
465	              this.client.customers.list(
466	                { email, limit },
467	                this.requestOptions(),
468	              ),
469	            ),
470	        ),
471	      );
472	    }
473	    if (name && name.trim().length >= 3) {
474	      const safeName = name.replace(/"/g, '');
475	      promises.push(
476	        this.withPermissionDiagnostics(
477	          'customers.search',
478	          ['customer_read'],
479	          () =>
480	            stripeBreaker.execute(() =>
481	              this.client.customers.search(
482	                {
483	                  query: `name~"${safeName}"`,
484	                  limit,
485	                },
486	                this.requestOptions(),
487	              ),
488	            ),
489	        ),
490	      );
491	    }
492	
493	    if (promises.length === 0) return [];
494	
495	    const results = await Promise.allSettled(promises);
496	    const seen = new Set<string>();
497	    const customers: Stripe.Customer[] = [];
498	    for (const r of results) {
499	      if (r.status !== 'fulfilled') continue;
500	      for (const customer of r.value.data) {
501	        if (excludeId && customer.id === excludeId) continue;
502	        if (seen.has(customer.id)) continue;
503	        seen.add(customer.id);
504	        customers.push(customer);
505	      }
506	    }
507	    return customers;
508	  }
