636	  private async listCustomerPaymentMethods(
637	    customerId: string,
638	  ): Promise<Stripe.PaymentMethod[]> {
639	    const results = await Promise.allSettled(
640	      CUSTOMER_PAYMENT_METHOD_TYPES.map(async (type) => {
641	        const data: Stripe.PaymentMethod[] = [];
642	        let startingAfter: string | undefined;
643	        do {
644	          const page = await this.withPermissionDiagnostics(
645	            `paymentMethods.list.${type}`,
646	            ['payment_method_read'],
647	            () =>
648	              stripeBreaker.execute(() =>
649	                this.client.paymentMethods.list(
650	                  {
651	                    customer: customerId,
652	                    type: type as Stripe.PaymentMethodListParams.Type,
653	                    limit: 100,
654	                    ...(startingAfter ? { starting_after: startingAfter } : {}),
655	                  },
656	                  this.requestOptions(),
657	                ),
658	              ),
659	          );
660	          data.push(...page.data);
661	          startingAfter =
662	            page.has_more && page.data.length > 0
663	              ? page.data[page.data.length - 1].id
664	              : undefined;
665	        } while (startingAfter);
666	        return data;
667	      }),
668	    );
669	
670	    const paymentMethods: Stripe.PaymentMethod[] = [];
671	    let firstError: unknown = null;
672	    for (const result of results) {
673	      if (result.status === 'fulfilled') {
674	        paymentMethods.push(...result.value);
675	      } else {
676	        firstError ??= result.reason;
677	      }
678	    }
679	
680	    if (
681	      paymentMethods.length === 0 &&
682	      firstError &&
683	      results.every((r) => r.status === 'rejected')
684	    ) {
685	      throw firstError;
686	    }
687	
688	    return paymentMethods;
689	  }
