691	  private async listPendingBankSetupIntentPaymentMethods(
692	    customerId: string,
693	    knownPaymentMethodIds: Set<string>,
694	  ): Promise<Stripe.PaymentMethod[]> {
695	    const pendingPaymentMethods: Stripe.PaymentMethod[] = [];
696	    let startingAfter: string | undefined;
697	
698	    do {
699	      const page = await this.withPermissionDiagnostics(
700	        'setupIntents.list.pending_bank_payment_methods',
701	        ['setup_intent_read', 'payment_method_read'],
702	        () =>
703	          stripeBreaker.execute(() =>
704	            this.client.setupIntents.list(
705	              {
706	                customer: customerId,
707	                limit: 100,
708	                ...(startingAfter ? { starting_after: startingAfter } : {}),
709	              },
710	              this.requestOptions(),
711	            ),
712	          ),
713	      );
714	
715	      for (const setupIntent of page.data) {
716	        if (!PENDING_BANK_SETUP_INTENT_STATUSES.has(setupIntent.status)) {
717	          continue;
718	        }
719	        if (!setupIntent.payment_method) continue;
720	        if (!setupIntent.payment_method_types.includes('us_bank_account')) {
721	          continue;
722	        }
723	
724	        const paymentMethodId =
725	          typeof setupIntent.payment_method === 'string'
726	            ? setupIntent.payment_method
727	            : setupIntent.payment_method.id;
728	        if (!paymentMethodId || knownPaymentMethodIds.has(paymentMethodId)) {
729	          continue;
730	        }
731	
732	        const paymentMethod =
733	          typeof setupIntent.payment_method === 'string'
734	            ? await this.retrievePaymentMethod(paymentMethodId)
735	            : setupIntent.payment_method;
736	        if (paymentMethod.type !== 'us_bank_account') continue;
737	
738	        knownPaymentMethodIds.add(paymentMethod.id);
739	        pendingPaymentMethods.push(paymentMethod);
740	      }
741	
742	      startingAfter =
743	        page.has_more && page.data.length > 0
744	          ? page.data[page.data.length - 1].id
745	          : undefined;
746	    } while (startingAfter);
747	
748	    return pendingPaymentMethods;
749	  }
