751	  async syncStudentPaymentMethods(args: {
752	    locationId: string;
753	    studentId: string;
754	    stripeCustomerId: string;
755	  }): Promise<{
756	    imported: number;
757	    existing: number;
758	    updated: number;
759	    removed: number;
760	    total: number;
761	  }> {
762	    const customer = await this.withPermissionDiagnostics(
763	      'customers.retrieve.expand_default_payment_method',
764	      ['customer_read', 'payment_method_read'],
765	      () =>
766	        stripeBreaker.execute(() =>
767	          this.client.customers.retrieve(
768	            args.stripeCustomerId,
769	            {
770	              expand: ['invoice_settings.default_payment_method'],
771	            },
772	            this.requestOptions(),
773	          ),
774	        ),
775	    );
776	    if ((customer as { deleted?: boolean }).deleted) {
777	      throw new SchoolStripeServiceError(
778	        'STRIPE_CUSTOMER_DELETED',
779	        `Stripe customer ${args.stripeCustomerId} has been deleted.`,
780	      );
781	    }
782	
783	    const defaultPaymentMethodId = getDefaultPaymentMethodId(
784	      customer as Stripe.Customer,
785	    );
786	    const attachedPaymentMethods = await this.listCustomerPaymentMethods(
787	      args.stripeCustomerId,
788	    );
789	    const knownPaymentMethodIds = new Set(
790	      attachedPaymentMethods.map((pm) => pm.id),
791	    );
792	    const pendingBankPaymentMethods =
793	      await this.listPendingBankSetupIntentPaymentMethods(
794	        args.stripeCustomerId,
795	        knownPaymentMethodIds,
796	      );
797	    const attachedMethods = attachedPaymentMethods
798	      .map((pm) =>
799	        normalizePaymentMethod(pm, defaultPaymentMethodId, {
800	          bankVerifiedFallback: true,
801	        }),
802	      )
803	      .filter((pm): pm is NormalizedPaymentMethod => pm != null);
804	    const pendingMethods = pendingBankPaymentMethods
805	      .map((pm) =>
806	        normalizePaymentMethod(pm, defaultPaymentMethodId, {
807	          bankVerifiedFallback: false,
808	        }),
809	      )
810	      .filter((pm): pm is NormalizedPaymentMethod => pm != null);
811	    const methods = [...attachedMethods, ...pendingMethods];
812	
813	    const existing = await db
814	      .select({
815	        id: schema.studentPaymentCards.id,
816	        stripePaymentMethodId: schema.studentPaymentCards.stripePaymentMethodId,
817	      })
818	      .from(schema.studentPaymentCards)
819	      .where(
820	        and(
