1392	  async confirmStudentStripeReconciliation(args: {
1393	    locationId: string;
1394	    studentId: string;
1395	    stripeCustomerId: string;
1396	    decisions: StudentStripeReconciliationDecision[];
1397	  }): Promise<StudentStripeReconciliationConfirmResult> {
1398	    const preview = await this.previewStudentStripeReconciliation(args);
1399	    const byKey = new Map(
1400	      preview.items.map((item) => [
1401	        `${item.recordType}:${item.stripeId}`,
1402	        item,
1403	      ]),
1404	    );
1405	    const invoices = await this.listCustomerInvoices(args.stripeCustomerId);
1406	    const paymentIntents = await this.listCustomerPaymentIntents(
1407	      args.stripeCustomerId,
1408	    );
1409	    const invoiceById = new Map(
1410	      invoices.data.map((invoice) => [invoice.id, invoice]),
1411	    );
1412	    const paymentById = new Map(
1413	      paymentIntents.data.map((paymentIntent) => [
1414	        paymentIntent.id,
1415	        paymentIntent,
1416	      ]),
1417	    );
1418	
1419	    const result: StudentStripeReconciliationConfirmResult = {
1420	      imported: 0,
1421	      matched: 0,
1422	      ignored: 0,
1423	      skipped: 0,
1424	      conflicts: 0,
1425	      balanceImpactCents: 0,
1426	      results: [],
1427	    };
1428	
1429	    const seen = new Set<string>();
1430	    for (const decision of args.decisions) {
1431	      const key = `${decision.recordType}:${decision.stripeId}`;
1432	      if (seen.has(key)) {
1433	        result.skipped += 1;
1434	        result.results.push({
1435	          ...decision,
1436	          status: 'skipped',
1437	          balanceImpactCents: 0,
1438	          reason: 'Duplicate decision in request',
1439	        });
1440	        continue;
1441	      }
1442	      seen.add(key);
1443	
1444	      const item = byKey.get(key);
1445	      if (!item) {
1446	        result.skipped += 1;
1447	        result.results.push({
1448	          ...decision,
1449	          status: 'skipped',
1450	          balanceImpactCents: 0,
1451	          reason: 'Stripe record not available in preview',
1452	        });
1453	        continue;
1454	      }
1455	
1456	      if (decision.action === 'ignore') {
1457	        result.ignored += 1;
1458	        result.results.push({
1459	          ...decision,
1460	          status: 'ignored',
1461	          balanceImpactCents: 0,
1462	        });
1463	        continue;
1464	      }
1465	
1466	      if (item.disposition === 'conflict' && decision.action !== 'match') {
1467	        result.conflicts += 1;
1468	        result.results.push({
1469	          ...decision,
1470	          status: 'conflict',
1471	          balanceImpactCents: 0,
1472	          reason: item.conflictReason ?? 'Conflict requires review',
1473	        });
1474	        continue;
1475	      }
1476	
1477	      if (decision.recordType === 'invoice') {
1478	        const invoice = invoiceById.get(decision.stripeId);
1479	        if (!invoice) {
1480	          result.skipped += 1;
1481	          result.results.push({
1482	            ...decision,
1483	            status: 'skipped',
1484	            balanceImpactCents: 0,
1485	            reason: 'Stripe invoice not found',
1486	          });
1487	          continue;
1488	        }
1489	        if (decision.action === 'match') {
1490	          const matched = await this.matchInvoiceToExisting(
1491	            decision.matchId ?? item.suggestedMatchId,
1492	            invoice,
1493	          );
1494	          result.matched += matched ? 1 : 0;
1495	          result.skipped += matched ? 0 : 1;
1496	          result.results.push({
1497	            ...decision,
1498	            status: matched ? 'matched' : 'skipped',
1499	            balanceImpactCents: 0,
1500	            reason: matched ? undefined : 'Existing invoice match not found',
1501	          });
1502	          continue;
1503	        }
1504	        const importResult = await this.importStripeInvoice({
1505	          locationId: args.locationId,
1506	          studentId: args.studentId,
1507	          invoice,
1508	        });
1509	        result.imported += importResult.imported;
1510	        result.skipped += importResult.skipped;
1511	        result.balanceImpactCents += importResult.balanceImpactCents;
1512	        result.results.push({
1513	          ...decision,
1514	          status: importResult.imported ? 'imported' : 'skipped',
1515	          balanceImpactCents: importResult.balanceImpactCents,
1516	          reason: importResult.imported ? undefined : 'Already imported',
1517	        });
1518	        continue;
1519	      }
1520	
1521	      if (decision.recordType === 'payment') {
1522	        const paymentIntent = paymentById.get(decision.stripeId);
1523	        if (!paymentIntent) {
1524	          result.skipped += 1;
1525	          result.results.push({
1526	            ...decision,
1527	            status: 'skipped',
1528	            balanceImpactCents: 0,
1529	            reason: 'Stripe payment not found',
1530	          });
1531	          continue;
1532	        }
1533	        if (decision.action === 'match') {
1534	          const matched = await this.matchPaymentToExisting(
1535	            decision.matchId ?? item.suggestedMatchId,
1536	            paymentIntent,
1537	          );
1538	          result.matched += matched ? 1 : 0;
1539	          result.skipped += matched ? 0 : 1;
1540	          result.results.push({
1541	            ...decision,
1542	            status: matched ? 'matched' : 'skipped',
1543	            balanceImpactCents: 0,
1544	            reason: matched ? undefined : 'Existing payment match not found',
1545	          });
1546	          continue;
1547	        }
1548	        const importResult = await this.importStripePaymentIntent({
1549	          locationId: args.locationId,
1550	          studentId: args.studentId,
1551	          paymentIntent,
1552	        });
1553	        result.imported += importResult.imported;
1554	        result.skipped += importResult.skipped;
1555	        result.balanceImpactCents += importResult.balanceImpactCents;
1556	        result.results.push({
1557	          ...decision,
1558	          status: importResult.imported ? 'imported' : 'skipped',
1559	          balanceImpactCents: importResult.balanceImpactCents,
1560	          reason: importResult.imported ? undefined : 'Already imported',
1561	        });
1562	        continue;
1563	      }
1564	
1565	      result.skipped += 1;
1566	      result.results.push({
1567	        ...decision,
1568	        status: 'skipped',
1569	        balanceImpactCents: 0,
1570	        reason: 'Record type is review-only',
1571	      });
1572	    }
1573	
1574	    return result;
1575	  }
