1901	function isStripeCredentialAuthError(err: unknown): boolean {
1902	  if (typeof err !== 'object' || err === null) return false;
1903	  const rec = err as {
1904	    code?: unknown;
1905	    raw?: { code?: unknown; statusCode?: unknown; type?: unknown };
1906	    statusCode?: unknown;
1907	    type?: unknown;
1908	  };
1909	  const code = typeof rec.code === 'string' ? rec.code : rec.raw?.code;
1910	  const statusCode =
1911	    typeof rec.statusCode === 'number' ? rec.statusCode : rec.raw?.statusCode;
1912	  const type = typeof rec.type === 'string' ? rec.type : rec.raw?.type;
1913	  return (
1914	    statusCode === 401 ||
1915	    statusCode === 403 ||
1916	    type === 'StripeAuthenticationError' ||
1917	    type === 'StripePermissionError' ||
1918	    code === 'invalid_api_key' ||
1919	    code === 'platform_api_key_expired' ||
1920	    code === 'application_access_not_authorized' ||
1921	    code === 'account_invalid' ||
1922	    code === 'permission_error'
1923	  );
1924	}
