1991	function normalizeStripeInvoice(
1992	  invoice: Stripe.Invoice,
1993	  stripeAccountId: string,
1994	): NormalizedStripeInvoice {
1995	  const amount = invoice.total ?? invoice.amount_due ?? 0;
1996	  const status = mapStripeInvoiceStatus(invoice.status);
1997	  const balanceImpactCents = -Math.abs(amount);
1998	  const lineItems =
1999	    invoice.lines?.data.map((line) => {
2000	      const quantity = line.quantity ?? 1;
2001	      const lineAttribution = extractDirectInvoiceAttribution(
2002	        (line as { metadata?: Record<string, unknown> | null }).metadata,
2003	      );
2004	      return {
2005	        stripeLineItemId: line.id,
2006	        description: line.description ?? 'Stripe invoice line',
2007	        quantity,
2008	        rate: quantity > 0 ? centsToDollars((line.amount ?? 0) / quantity) : 0,
2009	        amount: centsToDollars(line.amount ?? 0),
2010	        ...lineAttribution,
2011	      };
2012	    }) ?? [];
2013	  const invoiceAttribution = extractDirectInvoiceAttribution(invoice.metadata);
2014	  const attributedInvoice = populateDirectInvoiceAttributionIds({
2015	    lineItems,
2016	    metadata: {
2017	      stripeImported: true,
2018	      stripeAccountId,
2019	      stripeInvoiceId: invoice.id,
2020	      stripeInvoiceNumber: invoice.number ?? null,
2021	      stripeInvoiceStatus: invoice.status ?? null,
2022	      hostedInvoiceUrl: invoice.hosted_invoice_url ?? null,
2023	      invoicePdf: invoice.invoice_pdf ?? null,
2024	      eventDate: new Date(invoice.created * 1000).toISOString(),
2025	      invoiceDate: new Date(invoice.created * 1000).toISOString(),
2026	      type: 'Debit',
2027	      ...invoiceAttribution,
2028	    },
2029	  });
2030	
2031	  return {
2032	    amount,
2033	    balanceImpactCents,
2034	    description:
2035	      invoice.description ?? invoice.number ?? `Stripe invoice ${invoice.id}`,
2036	    status,
2037	    dueDate: invoice.due_date ? new Date(invoice.due_date * 1000) : null,
2038	    paidAt: invoice.status_transitions?.paid_at
2039	      ? new Date(invoice.status_transitions.paid_at * 1000)
2040	      : null,
2041	    lineItems: attributedInvoice.lineItems as Array<Record<string, unknown>>,
2042	    metadata: attributedInvoice.metadata,
2043	  };
2044	}
