2046	function mapStripeInvoiceStatus(status: Stripe.Invoice.Status | null): string {
2047	  switch (status) {
2048	    case 'paid':
2049	      return 'Completed';
2050	    case 'open':
2051	      return 'Approved';
2052	    case 'void':
2053	      return 'void';
2054	    case 'uncollectible':
2055	      return 'failed';
2056	    default:
2057	      return 'pending';
2058	  }
2059	}
