2078	    ),
2079	    ignored: items.filter((item) => item.disposition === 'ignored'),
2080	    conflicts: items.filter((item) => item.disposition === 'conflict'),
2081	    projectedBalanceImpactCents: items.reduce(
2082	      (sum, item) =>
