2090	function previewInvoice(
2091	  invoice: Stripe.Invoice,
2092	  stripeAccountId: string,
2093	  localInvoices: LocalInvoiceForReconciliation[],
2094	  studentId: string,
2095	  schoolId: string,
2096	): StudentStripeReconciliationPreviewItem {
2097	  const normalized = normalizeStripeInvoice(invoice, stripeAccountId);
2098	  const exact = localInvoices.find(
2099	    (local) =>
2100	      local.stripeAccountId === stripeAccountId &&
2101	      local.stripeInvoiceId === invoice.id,
2102	  );
2103	  const conflict = exact && exact.studentId !== studentId;
2104	  const suggested =
2105	    exact ?? bestInvoiceMatch(normalized, localInvoices, studentId);
2106	  const score = exact ? 1 : suggested ? scoreInvoice(normalized, suggested) : 0;
2107	  const disposition = conflict
2108	    ? 'conflict'
2109	    : exact
2110	      ? 'ignored'
