35	 * (02:00 CT) daily — well after the merge-freeze / promotion window.
36	 */
37	export async function GET(request: NextRequest) {
38	  return Sentry.withMonitor(
39	    'stripe-mapping-sweep-cron',
40	    async () => {
41	      try {
