53	          );
54	          return NextResponse.json({ ok: true, ...result });
55	        }
56	
57	        const byStatus = result.findings.reduce<Record<string, number>>(
58	          (acc, f) => {
59	            acc[f.status] = (acc[f.status] ?? 0) + 1;
60	            return acc;
61	          },
62	          {},
63	        );
64	
65	        const topFindings = result.findings
66	          .slice()
67	          .sort((a, b) => {
68	            const aSpend = a.alternativeCandidates.reduce(
69	              (s, c) => s + c.totalSpentCents,
70	              0,
71	            );
72	            const bSpend = b.alternativeCandidates.reduce(
73	              (s, c) => s + c.totalSpentCents,
74	              0,
75	            );
76	            return bSpend - aSpend;
77	          })
